function loadSubjects() {
  const raw = store.get(KEYS.subjects, null);
  const src = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : null;
  const out = {};
  const defs = isLegacyKid() ? DEFAULT_SUBJECTS : GENERIC_SUBJECTS;
  Object.keys(src || defs).forEach((name, i) => {
    const s = (src ? src[name] : defs[name]);
    const def = defs[name] || {};
    const o = s && typeof s === 'object' ? s : {};
    out[name] = {
      color: safeColor(o.color, safeColor(def.color, PALETTE[i % PALETTE.length])),
      emoji: typeof o.emoji === 'string' && o.emoji ? o.emoji.slice(0, 8) : (def.emoji || '📚'),
      materials: cleanMaterials(o.materials, def.materials || [])
    };
    if (o.fixed === true) out[name].fixed = true;
  });
  // Gli ID dei libri devono restare gli stessi tra un'apertura e l'altra, altrimenti le spunte si perdono.
  if (!src || JSON.stringify(out) !== JSON.stringify(src)) store.set(KEYS.subjects, out, true);
  return out;
}
function loadSchedule() {
  const raw = store.get(KEYS.schedule, null);
  const out = {};
  DAYS.forEach((d) => {
    const v = raw && Array.isArray(raw[d]) ? raw[d] : (isLegacyKid() ? DEFAULT_SCHEDULE[d] : []);
    out[d] = v.map((x) => String(x).slice(0, 60));
  });
  return out;
}
const saveSubjects = () => store.set(KEYS.subjects, subjects);
const saveSchedule = () => store.set(KEYS.schedule, schedule);
const saveChecks = () => store.set(KEYS.checks, checks);

/* ---------- giorni e date ---------- */
function defaultDay(now = new Date()) {
  const dow = now.getDay(); // 0 dom … 6 sab
  if (dow >= 1 && dow <= 5) {
    if (now.getHours() < SCHOOL_END_HOUR) return DAYS[dow - 1];
    return dow === 5 ? DAYS[0] : DAYS[dow];
  }
  return DAYS[0];
}
/* Data in cui quel giorno di scuola va "usato": le spunte valgono solo per quella data. */
function targetDate(day, now = new Date()) {
  const idx = DAYS.indexOf(day) + 1;
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  let diff = (idx - d.getDay() + 7) % 7;
  if (diff === 0 && now.getHours() >= SCHOOL_END_HOUR) diff = 7;
  d.setDate(d.getDate() + diff);
  return { iso: isoDate(d), diff };
}
function whenLabel(day) {
  const { diff } = targetDate(day);
  return diff === 0 ? 'Oggi' : diff === 1 ? 'Domani' : diff === 2 ? 'Dopodomani' : `tra ${diff} giorni`;
}

/* ---------- materie / lista zaino ---------- */
function findSubject(raw) {
  const n = norm(raw);
  if (!n) return null;
  const names = Object.keys(subjects);
  return names.find((k) => norm(k) === n) || names.find((k) => n.includes(norm(k))) || null;
}
function parseHour(raw) {
  return String(raw).split('/').map((s) => s.trim()).filter(Boolean)
    .map((part) => ({ raw: part, key: findSubject(part) }));
}
/* Ogni libro compare UNA volta, anche se la materia ha più ore. */
function packList(day) {
  const order = [];
  const map = new Map();
  const fixed = subjects[FIXED_KEY];
  /* «Sempre nello zaino» (astuccio, diario…): una volta sola per ogni giorno con lezioni, non per ogni ora */
  if (fixed && fixed.materials.length && (schedule[day] || []).length) {
    map.set(FIXED_KEY, { key: FIXED_KEY, label: FIXED_KEY, hours: [], mats: fixed.materials, fixed: true }); order.push(FIXED_KEY);
  }
  (schedule[day] || []).forEach((hourRaw, h) => {
    parseHour(hourRaw).forEach(({ raw, key }) => {
      if (key === FIXED_KEY) return;
      const id = key || 'unk:' + norm(raw);
      if (!map.has(id)) { map.set(id, { key, label: key || raw, hours: [], mats: key ? subjects[key].materials : [] }); order.push(id); }
      map.get(id).hours.push(h + 1);
    });
  });
  return order.map((id) => map.get(id));
}
function dayItems(day) { const ids = []; packList(day).forEach((g) => g.mats.forEach((m) => ids.push(m.id))); return ids; }
function dayChecks(day) {
  const t = targetDate(day).iso;
  if (!checks[day] || checks[day].date !== t) checks[day] = { date: t, items: {} };
  return checks[day].items;
}
function progress(day) {
  const ids = dayItems(day); const c = dayChecks(day);
  const done = ids.filter((id) => c[id]).length;
  return { total: ids.length, done, pct: ids.length ? Math.round(done / ids.length * 100) : 0 };
}
function missingNames(day) {
  const c = dayChecks(day); const out = [];
  packList(day).forEach((g) => g.mats.forEach((m) => { if (!c[m.id]) out.push(m.name); }));
  return out;
}
function findMaterial(id) {
  for (const k of Object.keys(subjects)) { const m = subjects[k].materials.find((x) => x.id === id); if (m) return { key: k, mat: m }; }
  return null;
}
function recordCompletion(day) {
  const p = progress(day);
  const date = targetDate(day).iso;
  if (!p.total || p.done !== p.total || progressLog.completed[date]) return;
  const next = {
    completed: Object.assign({}, progressLog.completed, {
      [date]: { day, completedAt: new Date().toISOString(), done: p.done, total: p.total }
    })
  };
  if (store.set(KEYS.history, next, true)) progressLog = next;
}
function previousSchoolDate(dateIso) {
  const date = new Date(`${dateIso}T12:00:00`);
  do { date.setDate(date.getDate() - 1); } while (date.getDay() === 0 || date.getDay() === 6);
  return isoDate(date);
}
function renderHistory() {
  const completed = progressLog.completed;
  const dates = Object.keys(completed).sort().reverse();
  const streak = streakInfo().cur;
  const prizeCount = Object.keys(rewards.draws).length;
  $('stats-summary').textContent = `${dates.length} giornate · serie ${streak} · ${prizeCount} premi · ${rewards.tickets} ticket`;
  $('history-list').innerHTML = dates.length ? dates.slice(0, 5).map((date) => {
    const entry = completed[date];
    const prizeDraw = rewards.draws[date];
    const prize = prizeDraw && prizeFromDraw(prizeDraw);
    const dateLabel = new Date(`${date}T12:00:00`).toLocaleDateString('it-IT', { day: 'numeric', month: 'short', year: 'numeric' });
    return `<div class="history-row"><span><strong>${esc(entry.day)}</strong><span class="muted"> · ${esc(dateLabel)}</span></span>
      <span class="history-count">${entry.done}/${entry.total}</span><span class="history-prize">${prize ? `🎟️ ${esc(prize.title)}` : '✅ Completato'}</span></div>`;
  }).join('') : '<p class="muted small">Completa uno zaino per iniziare lo storico.</p>';
}

/* ---------- gioco: punti, livelli, adesivi, missione ---------- */
/* 100 livelli in 10 gradi da 10: all'inizio si sale quasi ogni giorno, poi serve sempre più impegno (circa 44.000 XP per il 100). */
const LEVEL_TIERS = [['Recluta', '🐣'], ['Esploratore', '🧭'], ['Cavaliere', '🛡️'], ['Campione', '🏅'], ['Eroe', '🦸'],
  ['Super Eroe', '⚡'], ['Mago dello zaino', '🧙'], ['Astronauta', '🚀'], ['Domatore di draghi', '🐉'], ['Leggenda', '👑']];
const LEVEL_MAX = LEVEL_TIERS.length * 10;
const levelXp = (i) => (i ? Math.round((4 * i * i + 50 * i) / 10) * 10 : 0);
const LEVELS = Array.from({ length: LEVEL_MAX }, (_, i) => {
  const [tier, emoji] = LEVEL_TIERS[Math.floor(i / 10)];
  return { n: i + 1, xp: levelXp(i), tier, emoji, name: `${tier} · liv. ${i + 1}` };
});
function levelInfo(xp) {
  let i = 0; LEVELS.forEach((l, k) => { if (xp >= l.xp) i = k; });
  if (!Number.isFinite(i)) i = 0;
  const cur = LEVELS[i], next = LEVELS[i + 1] || null;
  return { i, cur, next, pct: next ? Math.round((xp - cur.xp) / (next.xp - cur.xp) * 100) : 100, toNext: next ? next.xp - xp : 0 };
}
const saveGame = () => store.set(KEYS.game, game);
/* Modalità calma: niente animazioni né vibrazioni (utile se gli effetti distraggono o stancano). */
let calm = store.get('zaino_calm', null);
if (calm === null) calm = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
function ensureFixed() {
  if (game.fixedSeeded) return;
  game.fixedSeeded = true;
  if (!subjects[FIXED_KEY]) {
    const fx = { color: '#f59e0b', emoji: '🎒', fixed: true, materials: [
      { id: uid(), name: 'Astuccio', photo: '', barcode: '', cls: '', emoji: '✏️' },
      { id: uid(), name: 'Diario', photo: '', barcode: '', cls: '', emoji: '📓' }] };
    const rest = subjects; subjects = Object.assign({ [FIXED_KEY]: fx }, rest);
    saveSubjects();
  }
  saveGame();
}
function setCalm(v) {
  calm = !!v; store.set('zaino_calm', calm, true);
  document.documentElement.classList.toggle('calm', calm); $('calm-mode').checked = calm;
}
$('calm-mode').onchange = () => setCalm($('calm-mode').checked);
const buzz = (pattern) => { if (!calm && navigator.vibrate) { try { navigator.vibrate(pattern); } catch (e) { /* niente */ } } };
function xpPop(text) {
  if (calm) { toast(text); return; }
  const el = document.createElement('div'); el.className = 'xp-pop'; el.setAttribute('aria-hidden', 'true'); el.textContent = text;
  document.body.appendChild(el); setTimeout(() => el.remove(), 1500);
}
function grantXp(amount, label) {
  const before = levelInfo(game.xp).i;
  game.xp += amount; saveGame();
  xpPop(`+${amount} ⭐${label ? ' ' + label : ''}`);
  const after = levelInfo(game.xp);
  if (after.i > before) {
    const n = (after.i - before) * PACKS.level; game.packs += n; saveGame();
    const newTier = Math.floor(after.i / 10) > Math.floor(before / 10);
    toast(newTier ? `🎉 Sei diventato ${after.cur.emoji} ${after.cur.tier}! Livello ${after.cur.n} · +${n} ${plural(n, 'bustina', 'bustine')} 🎴`
      : `🎉 Livello ${after.cur.n}! ${after.cur.emoji} +${n} ${plural(n, 'bustina', 'bustine')} 🎴`); confetti(); buzz([60, 40, 60]); sfx('level');
  }
  checkBadges();
}
function awardXp(key, amount, label) {
  if (game.awarded[key]) return false;
  game.awarded[key] = 1;
  const keys = Object.keys(game.awarded);
  if (keys.length > 400) keys.slice(0, keys.length - 400).forEach((k) => { delete game.awarded[k]; });
  grantXp(amount, label);
  return true;
}
/* Bustine: quante se ne ricevono per ogni cosa fatta. */
const PACKS = { full: 1, book: 2, level: 1, badge: 2, gift: 3 };
const PACK_SIZE = 2;
function awardPack(key, n) { if (game.awarded[key]) return; game.awarded[key] = 1; grantPacks(n); }
function streakInfo() {
  const dates = Object.keys(progressLog.completed).sort();
  let best = 0, run = 0, prev = null;
  dates.forEach((d) => { run = prev && previousSchoolDate(d) === prev ? run + 1 : 1; prev = d; best = Math.max(best, run); });
  let cur = 0;
  if (dates.length) {
    const last = dates[dates.length - 1];
    const gap = (new Date(isoDate(new Date()) + 'T12:00:00') - new Date(last + 'T12:00:00')) / 86400000;
    if (gap <= 4) cur = run;
  }
  return { cur, best, total: dates.length };
}
function mascotMessage() {
  const p = progress(state.day), name = profile.name, left = missingNames(state.day);
  const pick = (arr) => arr[(p.done * 7 + p.total + DAYS.indexOf(state.day)) % arr.length];
  if (!p.total) return `Niente da preparare per ${state.day}: riposo da eroe! 😎`;
  if (p.pct === 100) return pick([`Missione compiuta, ${name}! Che squadra! 🎉`, 'Zaino pronto! Puoi essere fiero di te 🌟', 'Tutto fatto! Ora ti aspetta la ruota 🎡']);
  if (!p.done) return pick([`Ciao ${name}! Quale cosa vuoi trovare per prima? 🔍`, `Ci sono ${p.total} cose da trovare. Da dove partiamo? 🚀`, 'Pronto per una missione veloce? Scegli tu come iniziare 💪']);
  if (left.length === 1) return `Ne manca solo una: ${left[0]}! Ci sei quasi 🏁`;
  return pick([`Che bravo! Ne restano ${left.length}. Ti va di cercare ${left[0]}? 👀`, `Stai andando forte! Ancora ${left.length} cose ⚡`, `Ottimo ritmo, ${name}! Vai come preferisci 😎`]);
}
