    const t = dc.querySelector('.detail-tilt'); if (!t) return; const r = t.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)), y = Math.max(0, Math.min(1, (e.clientY - r.top) / r.height));
    set(t, ((0.5 - y) * 24).toFixed(1) + 'deg', ((x - 0.5) * 24).toFixed(1) + 'deg', (x * 100).toFixed(0) + '%', (y * 100).toFixed(0) + '%');
