function stickSticker(id) {
  const i = game.pending.indexOf(id); if (i < 0) return;
  game.pending.splice(i, 1); saveGame();
  const page = id.slice(0, 2), turned = page !== albumTheme;
  const a = STICKER_THEMES.findIndex((x) => x.id === albumTheme), b = STICKER_THEMES.findIndex((x) => x.id === page);
  albumTheme = page; albumAnim = id; renderAlbum(turned ? (b > a ? 1 : -1) : 0);
  const slot = $('alb-page').querySelector('.stick-in'); if (slot && slot.scrollIntoView) slot.scrollIntoView({ block: 'center', behavior: calm ? 'auto' : 'smooth' });
  buzz(25); sfx('reveal');
  const t = STICKER_THEMES.find((x) => x.id === page);
  if (stuckCount(page) >= t.items.length) { toast(`🏆 Pagina ${t.name} completa!`); confetti(); sfx('badge'); }
  else if (!game.pending.length) toast('✨ Tutte attaccate! Che bell\'album');
  renderGame();
}
function stickAll() {
  if (!game.pending.length) return;
  const n = game.pending.length, last = game.pending[game.pending.length - 1];
  game.pending = []; saveGame(); albumTheme = last.slice(0, 2); renderAlbum(1);
  buzz([30, 30, 30]); sfx('pack'); toast(`✨ ${n} figurine attaccate nell'album!`);
  renderGame();
}
