$('alb-prev').onclick = () => { const i = STICKER_THEMES.findIndex((x) => x.id === albumTheme); if (i > 0) gotoAlbumPage(STICKER_THEMES[i - 1].id); };
$('alb-next').onclick = () => { const i = STICKER_THEMES.findIndex((x) => x.id === albumTheme); if (i < STICKER_THEMES.length - 1) gotoAlbumPage(STICKER_THEMES[i + 1].id); };
