(() => { /* sfoglia con il dito */
  let x0 = null, y0 = 0;
  const pg = $('alb-page');
  pg.addEventListener('touchstart', (e) => { const t = e.touches[0]; x0 = t.clientX; y0 = t.clientY; }, { passive: true });
  pg.addEventListener('touchend', (e) => {
    if (x0 === null) return; const t = e.changedTouches[0], dx = t.clientX - x0, dy = t.clientY - y0; x0 = null;
    if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) (dx < 0 ? $('alb-next') : $('alb-prev')).click();
  }, { passive: true });
})();
/* Regalo per il nuovo album: qualche bustina per iniziare (una volta per figlio). */
function albumGift() {
  if (game.awarded['gift:album19']) return;
  game.awarded['gift:album19'] = 1; game.packs += PACKS.gift; saveGame();
  setTimeout(() => toast(`🎁 Regalo: ${PACKS.gift} bustine per il nuovo album! Aprile nella scheda Premi.`), 2600);
}
function renderWeekDots() {
  const base = targetDate(defaultDay()).iso, d0 = new Date(base + 'T12:00:00');
  const mon = new Date(d0); mon.setDate(d0.getDate() - ((d0.getDay() + 6) % 7));
  const todayIso = isoDate(new Date()); let n = 0;
  $('week-dots').innerHTML = DAYS.map((d, i) => {
    const dt = new Date(mon); dt.setDate(mon.getDate() + i);
    const iso = isoDate(dt), done = !!progressLog.completed[iso]; if (done) n++;
    return `<span class="wdot${done ? ' done' : ''}${iso === base ? ' cur' : ''}${iso === todayIso ? ' today' : ''}" title="${d}${done ? ': zaino pronto' : ''}"><i aria-hidden="true">${done ? '✓' : ''}</i><b>${d[0]}</b></span>`;
  }).join('') + `<span class="wdot-t">${n} su 5 questa settimana</span>`;
}
