const usedInSchedule = (name) => DAYS.some((d) => (schedule[d] || []).some((h) => parseHour(h).some((p) => p.key === name)));
const weekHours = () => DAYS.reduce((a, d) => a + (schedule[d] || []).length, 0);
const stripEmoji = (t) => String(t).replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '').replace(/\s+/g, ' ').trim();

/* L'orario di esempio (solo per il primo figlio, mai toccato) si può sostituire con uno vuoto. */
function isSampleSetup() {
  if (!isLegacyKid()) return false;
  const sameSchedule = DAYS.every((d) => JSON.stringify(schedule[d] || []) === JSON.stringify(DEFAULT_SCHEDULE[d] || []));
  const sameBooks = Object.keys(DEFAULT_SUBJECTS).every((k) => subjects[k] && subjects[k].materials.map((m) => m.name).join('|') === DEFAULT_SUBJECTS[k].materials.join('|'));
  return sameSchedule && sameBooks;
}
function guideStartBlank() {
  const next = {};
  if (subjects[FIXED_KEY]) next[FIXED_KEY] = subjects[FIXED_KEY];
  Object.entries(GENERIC_SUBJECTS).forEach(([k, v]) => {
    next[k] = { color: v.color, emoji: v.emoji, materials: v.materials.map((n) => ({ id: uid(), name: n, photo: '', barcode: '', cls: '' })) };
  });
  subjects = next;
  DAYS.forEach((d) => { schedule[d] = []; });
  saveSubjects(); saveSchedule();
}

